<script setup>
import {computed,ref,watch} from 'vue';
import {api} from '../services/accounting.js';
import {farmProductionError} from '../services/farms.js';
import {productionDecimal} from '../../../shared/farm-production.js';
import {scaled,fixed} from '../../../shared/farm-costs.js';
import {nextFarmLotCode} from '../../../shared/farm-lots.js';
import FormDialog from './FormDialog.vue';
const props=defineProps({farm:Object,lot:Object,closing:Boolean,lots:Array}),emit=defineEmits(['close','saved']);
const defaultCode=props.lot?.code||nextFarmLotCode(props.farm.code,props.lots||[]);
const form=ref({...props.lot,farm_id:props.farm.id,code:props.lot?.code||defaultCode,entry_date:props.lot?.entry_date||'',exit_date:props.lot?.exit_date||(props.closing?new Date().toLocaleDateString('sv-SE'):''),animals_in:props.lot?.animals_in??'',animals_out:props.lot?.animals_out??'',entry_kg_per_pig:props.lot?.entry_kg_per_pig??'',entry_price_per_pig:props.lot?.entry_price_per_pig??'',entry_cost_included:!!props.lot?.entry_cost_included,feed_opening_kg:props.lot?.feed_opening_kg??'',feed_closing_kg:props.lot?.feed_closing_kg??'',notes:props.lot?.notes||''});
const busy=ref(false),error=ref('');
watch(()=>form.value.exit_date,value=>{if(!value)form.value.animals_out='';});
const entry=computed(()=>{try{const value=form.value,pigs=BigInt(value.animals_in||0),weight=productionDecimal(value.entry_kg_per_pig,3),price=productionDecimal(value.entry_price_per_pig,2);return {kg:weight===null?'—':Number(fixed(pigs*scaled(weight,3),3)).toLocaleString('es-ES')+' kg',cost:price===null?'—':Number(fixed(pigs*scaled(price,2),2)).toLocaleString('es-ES',{style:'currency',currency:'EUR'})};}catch{return {kg:'—',cost:'—'};}});
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const value=form.value,result=await api('/farms/lots'+(value.id?'/'+value.id:''),{method:value.id?'PATCH':'POST',body:{...value,auto_code:!value.id&&value.code===defaultCode,exit_date:value.exit_date||null,animals_in:value.animals_in===''?null:Number(value.animals_in),animals_out:value.animals_out===''?null:Number(value.animals_out)}});emit('saved',result);}catch(cause){error.value=farmProductionError(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog :title="closing?'Cerrar lote · salida de animales':lot?'Editar lote':'Nuevo lote · entrada de animales'" :busy="busy" @close="emit('close')"><p><strong>{{ farm.name }}</strong></p><form class="farm-lot-form" @submit.prevent="save"><label for="lot-code">Lote / referencia<input id="lot-code" v-model="form.code" maxlength="40" required :disabled="busy"></label><h3>Entrada de animales</h3><div class="lot-form-columns"><label for="lot-entry">Fecha de entrada<input id="lot-entry" v-model="form.entry_date" type="date" required :disabled="busy"></label><label for="lot-animals-in">Animales de entrada<input id="lot-animals-in" v-model="form.animals_in" type="number" min="0" max="10000000" step="1" :required="!!form.entry_kg_per_pig||!!form.entry_price_per_pig" :disabled="busy"></label><label for="lot-entry-kg">Kilos por animal a la entrada<input id="lot-entry-kg" v-model="form.entry_kg_per_pig" inputmode="decimal" placeholder="Ej. 20,5" :disabled="busy"></label><label for="lot-entry-price">Precio por animal (sin IVA)<input id="lot-entry-price" v-model="form.entry_price_per_pig" inputmode="decimal" placeholder="Ej. 65,00" :disabled="busy"></label></div><p class="lot-entry-total">Peso total de entrada: <strong>{{ entry.kg }}</strong> · Compra de animales: <strong>{{ entry.cost }}</strong></p><label class="lot-check"><input v-model="form.entry_cost_included" type="checkbox" :disabled="busy">La compra de animales ya está incluida en una despesa importada</label><h3>Salida y cierre</h3><div class="lot-form-columns"><label for="lot-exit">Fecha de salida<input id="lot-exit" v-model="form.exit_date" type="date" :min="form.entry_date||undefined" :required="closing" :disabled="busy"></label><label for="lot-animals-out">Animales de salida (opcional)<input id="lot-animals-out" v-model="form.animals_out" type="number" min="0" max="10000000" step="1" :disabled="busy||!form.exit_date"></label></div><h3>Existencias de pienso</h3><div class="lot-form-columns"><label for="lot-feed-opening">Pienso inicial en silo (kg)<input id="lot-feed-opening" v-model="form.feed_opening_kg" inputmode="decimal" placeholder="0" :disabled="busy"></label><label for="lot-feed-closing">Pienso final después de traspasos (kg)<input id="lot-feed-closing" v-model="form.feed_closing_kg" inputmode="decimal" placeholder="Indica 0 si quedó vacío" :disabled="busy"></label></div><p class="muted">Las existencias finales deben reflejar el saldo después de los traspasos. El índice será provisional mientras falten datos de cierre.</p><label for="lot-notes">Notas<textarea id="lot-notes" v-model="form.notes" rows="2" maxlength="2000" :disabled="busy"></textarea></label><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><div class="actions"><button class="button primary" :disabled="busy">{{ busy?'Guardando…':closing?'Cerrar lote':'Guardar lote' }}</button><button type="button" class="button" :disabled="busy" @click="emit('close')">Cancelar</button></div></form></FormDialog></template>
<style scoped>.farm-lot-form{display:grid;gap:16px;margin-top:20px}.farm-lot-form h3{font-size:15px;border-bottom:1px solid #e0e6ed;padding-bottom:8px}.lot-form-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.lot-check{display:flex;gap:10px;align-items:center}.lot-check input{width:auto}.lot-entry-total{padding:12px;background:var(--primary-soft);border-radius:7px;font-size:13px}@media(max-width:550px){.lot-form-columns{grid-template-columns:1fr}}</style>
